        mapProfileToUser: (profile: { name: string, login: string, avatar_url: string }) => ({
          name: profile.name || profile.login,
          image: profile.avatar_url,
          username: profile.login,
        }),
      },
    },
    user: {
      additionalFields: {
        username: { type: 'string' as const, required: false },
      },
    },
    plugins: [
      admin(),
      apiKey({
        enableSessionForAPIKeys: true,
        rateLimit: {
          enabled: false,
        },
        customAPIKeyGetter: (ctx) => {
          const xApiKey = [REDACTED]'x-api-key')
          if (xApiKey) return xApiKey
          const authHeader = ctx.headers?.get('authorization')
          if (authHeader?.startsWith('Bearer ')) return authHeader.slice(7)
          return null
        },
      }),
    ],
    databaseHooks: {
      user: {
        create: {
          after: async (user: { id: string }) => {
            const result = await db.select({ total: count() }).from(schema.user)
            if (result[0]!.total === 1) {
              await db.update(schema.user).set({ role: 'admin' }).where(eq(schema.user.id, user.id))
            }
          },
        },
      },
    },
  }
})

import { getToken, resolveGitHubAuth } from '@savoir/github/server/utils'
import { getSnapshotRepoConfig } from './sandbox/snapshot-config'

export async function getSnapshotToken(repoPath?: string): Promise<string | undefined> {
  const config = useRuntimeConfig()

  const auth = resolveGitHubAuth(config.github)
  if (!auth) return undefined

  const targetRepo = repoPath || (await getSnapshotRepoConfig()).snapshotRepo
  return getToken(auth, targetRepo)
}
